parameters.jsonBody:
={
  "from": "Firstflight Travels <onboarding@resend.dev>",
  "to": ["{{ $json.email }}"],
  "subject": "✈️ Your Booking Confirmation - {{ $json.itemData?.name || 'Booking' }}",
  "html": "<div style='font-family: sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #eee; border-radius: 10px;'><h2 style='color: #121619; border-bottom: 2px solid #D4B15A; padding-bottom: 10px;'>Firstflight Booking Confirmation</h2><p>Hi <strong>{{ $json.name }}</strong>,</p><p>Your booking for <strong>{{ $json.itemData?.name || 'your trip' }}</strong> ({{ $json.itemType }}) has been successfully confirmed!</p><table style='width: 100%; border-collapse: collapse; margin: 20px 0;'><tr style='background: #f9f9f9;'><td style='padding: 10px; border: 1px solid #eee;'><strong>From</strong></td><td style='padding: 10px; border: 1px solid #eee;'>{{ $json.itemData?.from || $json.itemData?.city || 'N/A' }}</td></tr><tr><td style='padding: 10px; border: 1px solid #eee;'><strong>To</strong></td><td style='padding: 10px; border: 1px solid #eee;'>{{ $json.itemData?.to || 'N/A' }}</td></tr><tr style='background: #f9f9f9;'><td style='padding: 10px; border: 1px solid #eee;'><strong>Dates</strong></td><td style='padding: 10px; border: 1px solid #eee;'>{{ $json.itemData?.fromDate || 'N/A' }} to {{ $json.itemData?.toDate || 'N/A' }}</td></tr><tr><td style='padding: 10px; border: 1px solid #eee;'><strong>Total Paid</strong></td><td style='padding: 10px; border: 1px solid #eee;'>INR {{ $json.itemData?.price_inr || 0 }}</td></tr></table><p>Download your official PDF ticket directly here: <a href='{{ $json.pdf_url }}' style='color: #D4B15A; font-weight: bold;'>Get Ticket PDF</a></p><p>Have a wonderful journey!</p><hr style='border: 0; border-top: 1px solid #eee; margin-top: 30px;'><p style='font-size: 11px; color: #888; text-align: center;'>Firstflight Travels Private Ltd. 1800-FF-TRAVELS</p></div>",
  "attachments": [
    {
      "filename": "Firstflight_Ticket_{{ $json.userId }}.pdf",
      "path": "{{ $json.pdf_url }}"
    }
  ]
}

={
  "to": "{{ $json.phone }}",
  "text": "Hi {{ $json.name }},

Your Firstflight Booking is CONFIRMED!

Item: {{ $json.itemData?.name || 'Booking' }}
Price: INR {{ $json.itemData?.price_inr || '0' }}
PDF Ticket URL: {{ $json.pdf_url }}

Wish you a safe journey!"
}
